const STOPWORDS=new Set(['PIX','PAGAMENTO','PAGTO','TRANSFERENCIA','TRANSF','LTDA','ME','EPP','SA']);
export function normalizeText(value=''){return String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9 ]/g,' ').replace(/\s+/g,' ').trim();}
export function stableHash(value=''){const text=String(value);let h1=0x811c9dc5,h2=0x811c9dc5;for(let i=0;i<text.length;i++){h1=Math.imul(h1^text.charCodeAt(i),16777619);h2=Math.imul(h2^(text.charCodeAt(i)+i),16777619);}return(h1>>>0).toString(16).padStart(8,'0')+(h2>>>0).toString(16).padStart(8,'0');}
function amountCentsOf(tx){const value=Number(tx?.amountCents);if(!Number.isInteger(value)||value<0)throw new TypeError('amountCents must be a non-negative integer');return value;}
export function businessFingerprint(tx){if(!tx||!['credit','debit'].includes(tx.direction))throw new TypeError('transaction direction must be credit or debit');return stableHash([tx.accountId??'',tx.date??'',normalizeText(tx.normalized??tx.description??''),amountCentsOf(tx),tx.direction].join('|'));}
export function sourceFingerprint(tx,sourceIdentity={}){const source=String(sourceIdentity.source??tx?.source??'').trim();const documentId=String(sourceIdentity.documentId??sourceIdentity.fileHash??sourceIdentity.batchId??tx?.batchId??'').trim();const externalId=String(sourceIdentity.externalId??tx?.externalId??'').trim();const hasRowIndex=Number.isInteger(sourceIdentity.rowIndex);if(!source||(!documentId&&!externalId)||(!externalId&&!hasRowIndex))throw new TypeError('sourceFingerprint requires source plus externalId or documentId with rowIndex');return stableHash([source,documentId,externalId||`row:${sourceIdentity.rowIndex}`].join('|'));}
function condition(actual,rule){if(!rule)return true;const normalized=normalizeText(actual??'');const kind=rule.kind??'contains';if(kind==='regex')return new RegExp(String(rule.value??''),rule.flags??'i').test(normalized);const expected=normalizeText(rule.value??'');if(kind==='equals')return normalized===expected;if(kind==='startsWith')return normalized.startsWith(expected);if(kind==='endsWith')return normalized.endsWith(expected);return normalized.includes(expected);}
export function ruleMatches(tx,rule){if(!rule||rule.enabled===false)return false;const match=rule.match??{};if(match.direction&&match.direction!==tx.direction)return false;if(match.accountId&&match.accountId!==tx.accountId)return false;if(match.description&&!condition(tx.normalized??tx.description,match.description))return false;if(match.counterparty&&!condition(tx.counterparty??tx.description,{kind:'contains',value:match.counterparty}))return false;if(match.amountCents){const amount=amountCentsOf(tx);if(match.amountCents.min!=null&&amount<Number(match.amountCents.min))return false;if(match.amountCents.max!=null&&amount>Number(match.amountCents.max))return false;}return true;}
export function applyDeterministicRules(tx,rules=[]){const ordered=[...rules].map((rule,index)=>({rule,index})).filter(x=>x.rule?.enabled!==false).sort((a,b)=>(Number(b.rule.priority??0)-Number(a.rule.priority??0))||a.index-b.index);for(const {rule} of ordered){if(ruleMatches(tx,rule))return{matched:true,ruleId:String(rule.id??''),confidence:1,assignments:{...(rule.assign??{})},reason:rule.reason||`Regra determinística ${rule.id??'sem-id'} aplicada`};}return{matched:false,ruleId:null,confidence:0,assignments:{},reason:'Nenhuma regra determinística aplicável'};}
export function dedupeBySourceFingerprint(existing=[],incoming=[]){const seen=new Set(existing.map(x=>x?.sourceFingerprint).filter(Boolean)),accepted=[],duplicates=[];for(const item of incoming){if(!item?.sourceFingerprint)throw new TypeError('incoming transaction is missing sourceFingerprint');if(seen.has(item.sourceFingerprint))duplicates.push(item);else{seen.add(item.sourceFingerprint);accepted.push(item);}}return{accepted,duplicates};}
function dayDistance(a,b){const av=Date.parse(`${a}T00:00:00Z`),bv=Date.parse(`${b}T00:00:00Z`);return Number.isFinite(av)&&Number.isFinite(bv)?Math.abs(av-bv)/86400000:Number.POSITIVE_INFINITY;}
function nameScore(description,name){const tokens=normalizeText(name).split(' ').filter(t=>t.length>=3&&!STOPWORDS.has(t));if(!tokens.length)return 0;const d=normalizeText(description);return tokens.filter(t=>d.includes(t)).length/tokens.length;}
export function reconcileAccountTransfers(transactions=[],accounts=[],options={}){const maxDays=Number.isFinite(options.maxDays)?Number(options.maxDays):1;const byId=new Map(accounts.map(a=>[a.id,a]));const used=new Set(),internalTransfers=[],withdrawals=[],returns=[];for(let i=0;i<transactions.length;i++){const a=transactions[i];if(used.has(a.id))continue;for(let j=i+1;j<transactions.length;j++){const b=transactions[j];if(used.has(b.id)||a.accountId===b.accountId||a.direction===b.direction||Number(a.amountCents)!==Number(b.amountCents)||dayDistance(a.date,b.date)>maxDays)continue;const debit=a.direction==='debit'?a:b,credit=a.direction==='credit'?a:b;const da=byId.get(debit.accountId),ca=byId.get(credit.accountId);if(!da||!ca)continue;const pair={debitId:debit.id,creditId:credit.id,amountCents:Number(debit.amountCents),dayDistance:dayDistance(a.date,b.date)};if(da.ownership==='business'&&ca.ownership==='business')internalTransfers.push(pair);else if(da.ownership==='business'&&ca.ownership==='personal')withdrawals.push(pair);else if(da.ownership==='personal'&&ca.ownership==='business')returns.push(pair);else continue;used.add(a.id);used.add(b.id);break;}}return{internalTransfers,withdrawals,returns,matchedTransactionIds:[...used]};}
export function suggestReconciliation(transactions=[],obligations=[],confirmedMatches=[],options={}){const minConfidence=Number.isFinite(options.minConfidence)?Number(options.minConfidence):0.65;const result=[];for(const tx of transactions){if(tx.direction!=='debit')continue;const candidates=obligations.map(ob=>{const remaining=Number(ob.amountCents??0),target=Number(tx.amountCents??0),exact=remaining===target,ns=nameScore(tx.description,ob.beneficiaryName??ob.description??''),dd=dayDistance(tx.date,ob.dueDate);let score=(exact?0.55:0)+ns*0.30+(dd<=3?0.15:dd<=7?0.10:dd<=15?0.05:0);return{ob,remaining,target,exact,ns,dd,score};}).filter(x=>x.score>=minConfidence).sort((a,b)=>b.score-a.score);const best=candidates[0];if(best)result.push({transactionId:tx.id,allocations:[{obligationId:best.ob.id,amountCents:Math.min(best.target,best.remaining)}],confidence:best.score,kind:best.exact?'exact':'partial',reason:'Correspondência determinística por score',evidence:{nameScore:best.ns,dayDistance:best.dd,exactAmount:best.exact}});}return result.sort((a,b)=>b.confidence-a.confidence);}
export const BASIC_PT_BR_FINANCE_RULES=Object.freeze([{id:'ptbr-taxes',priority:80,match:{description:{kind:'regex',value:'\\b(SIMPLES|DARF|DAS|RECEITA FEDERAL|FGTS|INSS)\\b'}},assign:{category:'Tributos e encargos'}},{id:'ptbr-bank-fees',priority:70,match:{description:{kind:'regex',value:'\\b(TARIFA|IOF|JUROS)\\b'}},assign:{category:'Tarifas bancárias'}},{id:'ptbr-fuel',priority:60,match:{description:{kind:'regex',value:'\\b(POSTO|COMBUST|SHELL|IPIRANGA)\\b'}},assign:{category:'Combustível'}}]);
